(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-144":{scenario:{company:"Lantern Peak Securities",supervisor:{name:"Đinh Quốc Việt",role:{vi:"Trưởng phòng Phân tích",en:"Head of Equity Research"}},ref_code:"ER-2611",title:{vi:"Từ giá trị doanh nghiệp đến giá trị mỗi cổ phiếu.",en:"From enterprise value to value per share."},brief:{vi:"Bạn soát mô hình định giá ER-2611 cho cổ phiếu Frostline Logistics (dữ liệu mô phỏng). Mô hình chiết khấu dòng tiền tự do của doanh nghiệp (FCFF); sau khi dùng đúng tỷ lệ chiết khấu, giá trị doanh nghiệp (EV) là 12.600 tỷ đồng. Nợ vay 3.100 tỷ đồng, tiền và tương đương tiền 900 tỷ đồng, lợi ích cổ đông không kiểm soát 200 tỷ đồng, 250 triệu cổ phiếu đang lưu hành. Bản nháp chia thẳng EV cho số cổ phiếu. Sửa tỷ lệ chiết khấu và giá trị nội tại mỗi cổ phiếu.",en:"You are reviewing valuation model ER-2611 for Frostline Logistics shares (training data). The model discounts free cash flow to the firm (FCFF); with the correct discount rate, enterprise value (EV) is VND 12,600 billion. Debt is VND 3,100 billion, cash and equivalents VND 900 billion, non-controlling interests VND 200 billion, and 250 million shares are outstanding. The draft divides EV directly by the share count. Correct the discount rate and the intrinsic value per share."},reference_title:{vi:"Hướng dẫn định giá & bảng cân đối đã kiểm toán · ER-2611",en:"Valuation manual & audited balance sheet · ER-2611"},fields:[{id:"DISC_RATE",label:{vi:"Tỷ lệ chiết khấu cho FCFF",en:"Discount rate for FCFF"},initial:"KE",expected:"WACC",choices:["KE","WACC","KD"],reference:"Hướng dẫn định giá nội bộ",hint:{vi:"Dòng tiền thuộc về cả chủ nợ và cổ đông phải chiết khấu bằng chi phí vốn của toàn bộ nguồn tài trợ.",en:"Cash flow belonging to both lenders and shareholders is discounted at the cost of all funding sources."}},{id:"VALUE_PS",label:{vi:"Giá trị nội tại mỗi cổ phiếu (VND)",en:"Intrinsic value per share (VND)"},initial:"50400",expected:"40800",reference:"Cầu nối từ EV đến giá trị vốn chủ",ref_value:{vi:"EV 12.600 tỷ; nợ vay 3.100 tỷ; tiền 900 tỷ; lợi ích CĐ không kiểm soát 200 tỷ; 250 triệu cổ phiếu",en:"EV VND 12,600 bn; debt 3,100 bn; cash 900 bn; non-controlling interests 200 bn; 250 million shares"},hint:{vi:"Từ giá trị doanh nghiệp đi tới giá trị vốn chủ phải xử lý các khoản không thuộc cổ đông công ty mẹ và tiền dư.",en:"Going from EV to equity value requires handling claims outside parent shareholders and surplus cash."}}],sop32:{vi:"Giá trị vốn chủ = EV - nợ vay + tiền và tương đương tiền - lợi ích cổ đông không kiểm soát; giá trị mỗi cổ phiếu = giá trị vốn chủ / số cổ phiếu lưu hành, làm tròn đến đồng.",en:"Equity value = EV - debt + cash and equivalents - non-controlling interests; value per share = equity value / shares outstanding, rounded to the nearest dong."},context:{label:"MÔ HÌNH ĐỊNH GIÁ NHÁP / ER-2611",metrics:[{label:{vi:"Giá trị doanh nghiệp (EV)",en:"Enterprise value (EV)"},value:"12,600 bn VND"},{label:{vi:"Nợ vay ròng",en:"Net debt"},value:"2,200 bn VND"},{label:{vi:"Cổ phiếu lưu hành",en:"Shares outstanding"},value:"250,000,000"}]},crisis:{vi:"Một người quen làm ở phòng tài chính Frostline nhắn riêng: lợi nhuận quý 3 chưa công bố tăng gấp đôi. Trưởng bộ phận môi giới đề nghị bạn nâng khuyến nghị lên MUA và gửi trước cho nhóm khách hàng tổ chức ngay sáng nay.",en:"An acquaintance in Frostline's finance team privately tells you that unpublished Q3 profit doubled. The head of brokerage asks you to upgrade to BUY and send it to institutional clients first this morning."},options:{safe:{vi:"Không sử dụng hay chia sẻ thông tin chưa công bố, báo ngay bộ phận Tuân thủ để xử lý và đưa mã vào danh sách hạn chế; khuyến nghị chỉ dựa trên thông tin công khai và phát hành đồng thời cho mọi khách hàng.",en:"Neither use nor share the unpublished information, report it to Compliance at once so the stock goes on the restricted list; base ratings on public data only and release to all clients at the same time."},shortcut:{vi:"Nâng khuyến nghị lên MUA và gửi trước cho khách hàng tổ chức, ghi lý do là “triển vọng tích cực”.",en:"Upgrade to BUY and send it to institutional clients first, citing a “positive outlook”."},wait:{vi:"Giữ im lặng, không báo ai và tiếp tục làm như chưa nhận được tin nhắn.",en:"Stay silent, tell no one and carry on as if the message never arrived."}},questions:{vi:["Vì sao FCFF phải chiết khấu bằng WACC? Trình bày cầu nối từ EV đến giá trị mỗi cổ phiếu mà bạn đã tính lại.","Thông tin lợi nhuận chưa công bố là loại thông tin gì, sử dụng nó gây rủi ro pháp lý nào và bạn báo cáo cho ai?"],en:["Why must FCFF be discounted at WACC? Show the bridge from EV to value per share that you recalculated.","What kind of information is the unpublished profit, what legal risk comes from using it, and whom do you report to?"]},hints:{vi:["Đặt mô hình nháp cạnh hướng dẫn định giá và kiểm tra dòng tiền nào đang được chiết khấu bằng tỷ lệ nào.","Lập cầu nối từng bước từ EV sang giá trị vốn chủ trước khi chia cho số cổ phiếu ở SOP mục 3.2.","Đọc lại SOP mục 4.2: thông tin trọng yếu chưa công bố phải được báo bộ phận Tuân thủ, không dùng cho khuyến nghị."],en:["Place the draft model next to the valuation manual and check which cash flow uses which rate.","Build the EV to equity bridge step by step before dividing by shares in SOP 3.2.","Re-read SOP 4.2: material nonpublic information goes to Compliance and is never used for ratings."]}},learning:{summary:{vi:"Chuyên viên phân tích đầu tư cổ phiếu nghiên cứu ngành và doanh nghiệp niêm yết, xây dựng mô hình dự phóng tài chính, định giá bằng chiết khấu dòng tiền và so sánh bội số, rồi đưa ra khuyến nghị và giá mục tiêu cho nhà đầu tư. Giá trị tạo ra là thông tin độc lập, có cơ sở giúp thị trường định giá hiệu quả. Nghề đòi hỏi kỹ năng đọc báo cáo tài chính, mô hình hóa, viết báo cáo và tuân thủ nghiêm quy định về thông tin nội bộ, xung đột lợi ích.",en:"An equity research analyst studies industries and listed companies, builds financial forecast models, values shares with discounted cash flow and multiples, and issues ratings and target prices for investors. The value is independent, well-grounded information that helps markets price efficiently. The role requires financial statement analysis, modeling and writing skills, and strict compliance with insider information and conflict of interest rules."},responsibilities:{vi:["Theo dõi ngành, doanh nghiệp được phân công và cập nhật tin tức, kết quả kinh doanh công bố.","Xây dựng và cập nhật mô hình dự phóng doanh thu, lợi nhuận, dòng tiền.","Định giá bằng DCF và bội số so sánh, xác định giá mục tiêu và khuyến nghị.","Viết báo cáo phân tích, trình bày với nhà đầu tư tổ chức và đội môi giới.","Tuân thủ quy định về thông tin nội bộ, danh sách hạn chế và công bố xung đột lợi ích."],en:["Cover assigned sectors and companies and track news and published results.","Build and update forecast models for revenue, profit and cash flow.","Value shares with DCF and peer multiples and set target prices and ratings.","Write research reports and present to institutional investors and the sales team.","Follow insider information rules, the restricted list and conflict disclosures."]},competencies:[{name:{vi:"Phân tích báo cáo tài chính",en:"Financial statement analysis"},desc:{vi:"Chuẩn hóa số liệu, nhận diện khoản bất thường và chất lượng lợi nhuận.",en:"Normalize figures and spot one-offs and earnings quality issues."}},{name:{vi:"Định giá doanh nghiệp",en:"Equity valuation"},desc:{vi:"Áp dụng đúng FCFF với WACC, FCFE với chi phí vốn chủ và bội số P/E, EV/EBITDA.",en:"Apply FCFF with WACC, FCFE with cost of equity and P/E or EV/EBITDA multiples correctly."}},{name:{vi:"Hiểu ngành",en:"Industry insight"},desc:{vi:"Nắm động lực cung cầu, cạnh tranh, chính sách và chu kỳ của ngành theo dõi.",en:"Understand supply, demand, competition, policy and cycles of the covered sector."}},{name:{vi:"Viết & thuyết trình",en:"Writing & presenting"},desc:{vi:"Trình bày luận điểm đầu tư, rủi ro và giả định rõ ràng, ngắn gọn.",en:"Present the investment thesis, risks and assumptions clearly and briefly."}},{name:{vi:"Đạo đức & tuân thủ",en:"Ethics & compliance"},desc:{vi:"Không dùng thông tin trọng yếu chưa công bố, công bố xung đột lợi ích và giữ độc lập.",en:"Never use material nonpublic information, disclose conflicts and stay independent."}}],knowledge:{vi:["Luật Chứng khoán số 54/2019/QH14 và Nghị định 155/2020/NĐ-CP: cấm giao dịch nội gián, thao túng thị trường.","Thông tư 96/2020/TT-BTC hướng dẫn công bố thông tin trên thị trường chứng khoán.","Bộ Quy tắc đạo đức và Chuẩn mực hành nghề của CFA Institute về thông tin trọng yếu chưa công bố và cơ sở hợp lý của khuyến nghị.","Định giá DCF: FCFF chiết khấu bằng WACC, FCFE chiết khấu bằng chi phí vốn chủ theo CAPM, giá trị cuối kỳ.","Định giá so sánh P/E, P/B, EV/EBITDA và chuẩn hóa số liệu theo VAS, IFRS."],en:["Securities Law No. 54/2019/QH14 and Decree 155/2020/ND-CP: bans on insider trading and market manipulation.","Circular 96/2020/TT-BTC on information disclosure in the securities market.","The CFA Institute Code of Ethics and Standards on material nonpublic information and reasonable basis.","DCF valuation: FCFF at WACC, FCFE at the CAPM cost of equity, and terminal value.","Relative valuation with P/E, P/B and EV/EBITDA and normalizing data under VAS and IFRS."]},tools:["Microsoft Excel (mô hình định giá)","Hệ thống dữ liệu thị trường tài chính","Cổng công bố thông tin của sở giao dịch","Công cụ BI và trực quan hóa","Phần mềm soạn và phát hành báo cáo phân tích"],kpis:{vi:["Độ chính xác dự phóng lợi nhuận so với kết quả công bố.","Hiệu quả khuyến nghị so với chỉ số tham chiếu trong 12 tháng.","Số báo cáo phát hành đúng hạn sau khi doanh nghiệp công bố kết quả.","Xếp hạng đánh giá của khách hàng tổ chức."],en:["Earnings forecast accuracy versus reported results.","Rating performance against the benchmark over 12 months.","Reports published on time after results releases.","Institutional client rankings."]},day:[{time:"07:30",vi:"Đọc tin tức, công bố thông tin qua đêm và cập nhật nhanh cho đội môi giới.",en:"Read overnight news and disclosures and brief the sales team."},{time:"09:30",vi:"Cập nhật mô hình sau kết quả kinh doanh mới công bố của doanh nghiệp theo dõi.",en:"Update the model after a covered company's newly published results."},{time:"13:30",vi:"Tham gia buổi gặp nhà đầu tư do doanh nghiệp tổ chức, chỉ ghi nhận thông tin công khai.",en:"Join the company's investor meeting and record public information only."},{time:"15:30",vi:"Viết báo cáo cập nhật, rà soát giả định định giá với trưởng phòng.",en:"Write an update report and review valuation assumptions with the head of research."},{time:"17:00",vi:"Gửi báo cáo qua bộ phận Tuân thủ duyệt trước khi phát hành đồng thời cho khách hàng.",en:"Send the report through Compliance before simultaneous release to clients."}],mistakes:{vi:["Chiết khấu FCFF bằng chi phí vốn chủ hoặc FCFE bằng WACC, làm sai lệch giá trị.","Chia EV cho số cổ phiếu mà quên trừ nợ, cộng tiền và trừ lợi ích cổ đông không kiểm soát.","Dùng tin đồn hoặc thông tin nội bộ chưa công bố để thay đổi khuyến nghị."],en:["Discounting FCFF at the cost of equity or FCFE at WACC, distorting value.","Dividing EV by shares without subtracting debt, adding cash and removing non-controlling interests.","Changing ratings based on rumors or unpublished inside information."]},career:[{vi:"Trợ lý phân tích",en:"Research associate"},{vi:"Chuyên viên phân tích cổ phiếu",en:"Equity research analyst"},{vi:"Chuyên viên phân tích cấp cao / Trưởng nhóm ngành",en:"Senior analyst / Sector head"},{vi:"Giám đốc phân tích",en:"Director of research"}],glossary:[{term:"FCFF",vi:"Dòng tiền tự do của doanh nghiệp, dành cho cả chủ nợ và cổ đông sau đầu tư và vốn lưu động.",en:"Free cash flow to the firm, available to lenders and shareholders after capex and working capital."},{term:"WACC",vi:"Chi phí vốn bình quân gia quyền của vốn chủ và nợ vay sau thuế theo tỷ trọng thị trường.",en:"Weighted average cost of equity and after-tax debt at market weights."},{term:"Enterprise value",vi:"Giá trị doanh nghiệp: giá trị hoạt động kinh doanh cốt lõi thuộc về mọi nhà cung cấp vốn.",en:"The value of core operations belonging to all capital providers."},{term:"MNPI",vi:"Thông tin trọng yếu chưa công bố, có thể ảnh hưởng đến giá chứng khoán, bị cấm sử dụng để giao dịch.",en:"Material nonpublic information that could move prices and must not be used for trading."},{term:"Target price",vi:"Giá mục tiêu: giá trị dự kiến của cổ phiếu trong khoảng thời gian xác định, thường 12 tháng.",en:"The expected share value over a set horizon, usually 12 months."}],quiz:[{q:{vi:"EPS dự phóng 3.200 đồng, P/E mục tiêu 12,5 lần. Giá mục tiêu là bao nhiêu?",en:"Forecast EPS is VND 3,200 and the target P/E is 12.5x. What is the target price?"},options:{vi:["32.000 đồng","38.400 đồng","40.000 đồng","44.800 đồng"],en:["VND 32,000","VND 38,400","VND 40,000","VND 44,800"]},answer:2,explain:{vi:"Giá mục tiêu = EPS x P/E = 3.200 x 12,5 = 40.000 đồng.",en:"Target price = EPS x P/E = 3,200 x 12.5 = VND 40,000."}},{q:{vi:"Lãi suất phi rủi ro 4%, beta 1,2, phần bù rủi ro thị trường 7%. Chi phí vốn chủ theo CAPM là bao nhiêu?",en:"Risk-free rate 4%, beta 1.2, equity risk premium 7%. What is the CAPM cost of equity?"},options:{vi:["12,4%","11,0%","8,4%","13,2%"],en:["12.4%","11.0%","8.4%","13.2%"]},answer:0,explain:{vi:"Chi phí vốn chủ Ke = 4% + 1,2 x 7% = 12,4%.",en:"Ke = 4% + 1.2 x 7% = 12.4%."}},{q:{vi:"Bội số nào phù hợp hơn để so sánh các doanh nghiệp có cơ cấu nợ vay rất khác nhau?",en:"Which multiple is better for comparing companies with very different leverage?"},options:{vi:["P/E","EV/EBITDA","Tỷ suất cổ tức","P/B"],en:["P/E","EV/EBITDA","Dividend yield","P/B"]},answer:1,explain:{vi:"EV/EBITDA đo trên toàn bộ nguồn vốn trước chi phí lãi vay nên ít bị ảnh hưởng bởi cơ cấu vốn.",en:"EV/EBITDA works at the whole-capital level before interest, so leverage distorts it less."}},{q:{vi:"Bạn tình cờ nhận được kết quả kinh doanh chưa công bố của doanh nghiệp đang theo dõi. Bạn làm gì?",en:"You accidentally receive unpublished results of a covered company. What do you do?"},options:{vi:["Nâng khuyến nghị ngay để khách hàng có lợi","Chia sẻ cho trưởng bộ phận môi giới","Mua cổ phiếu cho tài khoản cá nhân","Không sử dụng, báo bộ phận Tuân thủ và chờ thông tin được công bố"],en:["Upgrade the rating at once to benefit clients","Share it with the head of brokerage","Buy the shares for your own account","Do not use it, report to Compliance and wait for public release"]},answer:3,explain:{vi:"Sử dụng thông tin nội bộ chưa công bố là hành vi bị cấm; phải báo Tuân thủ và chỉ dựa vào thông tin công khai.",en:"Using inside information is prohibited; report to Compliance and rely only on public information."}}],tools_en:["Microsoft Excel (valuation models)","Financial market data system","Stock exchange disclosure portal","BI and visualization tools","Research report authoring and publishing tool"]}}})})(window.KKR);
